require_once __DIR__.'/../bootstrap.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Método no permitido.',405);$d=jsonBody();$n=requiredText($d,'nombre',80);$a=requiredText($d,'apellido',80);$doc=requiredText($d,'documento',30);$email=trim((string)($d['email']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))fail('Email inválido.',422);$st=db()->prepare('INSERT INTO clientes(nombre,apellido,documento,email,telefono,direccion) VALUES(?,?,?,?,?,?)');try{$st->execute([$n,$a,$doc,$email?:null,trim((string)($d['telefono']??''))?:null,trim((string)($d['direccion']??''))?:null]);}catch(PDOException $e){if($e->getCode()==='23000')fail('Ya existe un cliente con ese documento o email.',409);throw $e;}respond(['id'=>(int)db()->lastInsertId(),'nombre'=>$n,'apellido'=>$a,'documento'=>$doc,'email'=>$email],201);
